-- The GitHub pull_request webhook of the policy check (issue #771, AC-10 follow-up): the per-tenant webhook secret and the
-- deliveries already handled.
--
-- github_webhook_secrets: one row per tenant (none: the receiver refuses every delivery). secret_enc is the shared secret
-- GitHub signs each delivery with (X-Hub-Signature-256), sealed with internal/seal (AES-256-GCM, AAD bound to tenant,
-- table and column); the API never returns it, only that it is set and when. It is generated by Tessera and shown once
-- (PUT /api/policy/github/app, rotate_webhook_secret).
--
-- github_webhook_deliveries: one row per X-GitHub-Delivery id handled, so a replayed delivery is refused. Rows expire
-- (expires_at) and are pruned when a new delivery is recorded; the insert is atomic, so two concurrent copies of one
-- delivery cannot both be handled.
--
-- Tenant-owned: tenant_id on every row and first in every key; neither table references another tenant table, so no
-- cross-tenant guard trigger is needed. Postgres: migration 0971.
CREATE TABLE IF NOT EXISTS github_webhook_secrets (
  tenant_id TEXT NOT NULL PRIMARY KEY REFERENCES tenants (id),
  secret_enc BLOB NOT NULL,
  set_at TEXT NOT NULL,
  set_by TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS github_webhook_deliveries (
  tenant_id TEXT NOT NULL REFERENCES tenants (id),
  delivery_id TEXT NOT NULL CHECK (length(delivery_id) BETWEEN 1 AND 100),
  expires_at TEXT NOT NULL,
  PRIMARY KEY (tenant_id, delivery_id)
);
CREATE INDEX IF NOT EXISTS ix_github_webhook_deliveries_expiry ON github_webhook_deliveries (tenant_id, expires_at);
